import sys

def next_greater_brute(nums):
    n = len(nums)
    res = [-1] * n
    for i in range(n):
        for k in range(1, n + 1):
            j = (i + k) % n
            if nums[j] > nums[i]:
                res[i] = nums[j]
                break
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, next_greater_brute(nums))))

import sys

def next_greater_opt(nums):
    n = len(nums)
    res = [-1] * n
    stack = []
    for i in range(2 * n):
        x = nums[i % n]
        while stack and x > nums[stack[-1]]:
            res[stack.pop()] = x
        if i < n:
            stack.append(i)
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, next_greater_opt(nums))))

import sys

def next_greater_best(nums):
    n = len(nums)
    res = [-1] * n
    stack = []
    in_stack = [False] * n
    for i in range(2 * n):
        x = nums[i % n]
        while stack and x > nums[stack[-1]]:
            j = stack.pop(); res[j] = x; in_stack[j] = False
        if i < n and not in_stack[i]:
            stack.append(i); in_stack[i] = True
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print(' '.join(map(str, next_greater_best(nums))))
